def compare_alloy_properties(compositions, temperature, phase='liquid'):
    results = []
    for i, comp in enumerate(compositions):
        r = call_tool('calculate_all_properties', composition=comp, temperature=temperature, phase=phase)
        label = '-'.join(f'{k}{v:.2f}' for k, v in comp.items())
        entry = {'alloy': label, 'composition': comp}
        if r.get('status') == 'success':
            alloy = r.get('alloy', {})
            entry['mixing_enthalpy_J'] = alloy.get('molar_enthalpy_J_per_mol')
            entry['gibbs_energy_J'] = alloy.get('gibbs_energy_J_per_mol')
            entry['entropy_J_K'] = alloy.get('entropy_J_per_mol_K')
        else:
            entry['error'] = r.get('message', 'unknown error')
        results.append(entry)
    return {'status': 'success', 'temperature_K': temperature, 'phase': phase, 'comparisons': results, 'count': len(results)}

def scan_binary_mixing_enthalpy(element_a, element_b, temperature, n_points=21, phase='liquid'):
    curve = []
    for i in range(n_points):
        x_b = i / (n_points - 1)
        if x_b < 0.001 or x_b > 0.999:
            continue
        comp = {element_a: round(1.0 - x_b, 4), element_b: round(x_b, 4)}
        r = call_tool('calculate_mixing_enthalpy', composition=comp, temperature=temperature, phase=phase)
        if r.get('status') == 'success':
            curve.append({'x_' + element_b: round(x_b, 4), 'H_mix_J': r.get('molar_enthalpy')})
    h_values = [p['H_mix_J'] for p in curve if p.get('H_mix_J') is not None]
    summary = {}
    if h_values:
        summary = {'min_H_mix': min(h_values), 'max_H_mix': max(h_values), 'min_at_x': curve[[p.get('H_mix_J') for p in curve].index(min(h_values))]['x_' + element_b]}
    return {'status': 'success', 'system': f'{element_a}-{element_b}', 'temperature_K': temperature, 'phase': phase, 'curve': curve, 'n_points': len(curve), 'summary': summary}

def multi_solute_liquidus_effect(solvent, solutes, solute_fraction=0.05):
    results = []
    base = call_tool('calculate_liquidus_temperature', composition={solvent: 1.0})
    base_T = base.get('liquidus_temperature') if base.get('status') == 'success' else None
    for sol in solutes:
        comp = {solvent: round(1.0 - solute_fraction, 4), sol: solute_fraction}
        r = call_tool('calculate_liquidus_temperature', composition=comp)
        entry = {'solute': sol, 'fraction': solute_fraction}
        if r.get('status') == 'success':
            T = r['liquidus_temperature']
            entry['liquidus_K'] = round(T, 1)
            entry['liquidus_C'] = round(T - 273.15, 1)
            if base_T:
                entry['depression_K'] = round(base_T - T, 1)
        else:
            entry['error'] = r.get('message', '')
        results.append(entry)
    results.sort(key=lambda x: x.get('depression_K', 0), reverse=True)
    return {'status': 'success', 'solvent': solvent, 'base_melting_K': base_T, 'solute_fraction': solute_fraction, 'results': results}

def composition_sensitivity_analysis(base_composition, vary_element, x_min=0.01, x_max=0.20, n_points=11):
    curve = []
    solvent = max(base_composition, key=base_composition.get)
    for i in range(n_points):
        x = x_min + (x_max - x_min) * i / (n_points - 1)
        comp = dict(base_composition)
        comp[vary_element] = x
        total_others = sum(v for k, v in comp.items() if k != solvent)
        comp[solvent] = max(1.0 - total_others, 0.01)
        r = call_tool('calculate_liquidus_temperature', composition=comp)
        pt = {'x_' + vary_element: round(x, 4)}
        if r.get('status') == 'success':
            pt['liquidus_K'] = round(r['liquidus_temperature'], 1)
            pt['liquidus_C'] = round(r['liquidus_temperature'] - 273.15, 1)
        else:
            pt['error'] = r.get('message', '')
        curve.append(pt)
    T_vals = [p['liquidus_K'] for p in curve if 'liquidus_K' in p]
    summary = {}
    if len(T_vals) >= 2:
        dT = T_vals[-1] - T_vals[0]
        dx = x_max - x_min
        summary = {'T_range_K': round(max(T_vals) - min(T_vals), 1), 'dT_dx': round(dT / dx, 1) if dx > 0 else 0, 'max_T_K': round(max(T_vals), 1), 'min_T_K': round(min(T_vals), 1)}
    return {'status': 'success', 'base_composition': base_composition, 'vary_element': vary_element, 'range': [x_min, x_max], 'curve': curve, 'summary': summary}

def activity_temperature_scan(composition, component, T_min=1200, T_max=2000, n_points=17, phase='liquid'):
    curve = []
    for i in range(n_points):
        T = T_min + (T_max - T_min) * i / (n_points - 1)
        r = call_tool('calculate_activity', composition=composition, component=component, temperature=T, phase=phase)
        pt = {'temperature_K': round(T, 1)}
        if r.get('status') == 'success':
            pt['activity'] = r.get('activity')
            pt['activity_coefficient'] = r.get('activity_coefficient')
        else:
            pt['error'] = r.get('message', '')
        curve.append(pt)
    return {'status': 'success', 'composition': composition, 'component': component, 'phase': phase, 'T_range': [T_min, T_max], 'curve': curve, 'n_points': len(curve)}

def interaction_matrix(solvent, solutes, temperature=1873):
    matrix = {}
    for i_elem in solutes:
        row = {}
        for j_elem in solutes:
            r = call_tool('get_interaction_coefficient', solvent=solvent, solute_i=i_elem, solute_j=j_elem, temperature=temperature)
            if r.get('status') == 'success':
                row[j_elem] = r.get('epsilon_i_j')
            else:
                row[j_elem] = None
        matrix[i_elem] = row
    return {'status': 'success', 'solvent': solvent, 'temperature_K': temperature, 'solutes': solutes, 'matrix': matrix}

def alloy_design_report(composition, temperature=0):
    report = {'composition': composition}
    liq = call_tool('calculate_liquidus_temperature', composition=composition)
    if liq.get('status') == 'success':
        report['liquidus_K'] = round(liq['liquidus_temperature'], 1)
        report['liquidus_C'] = round(liq['liquidus_temperature'] - 273.15, 1)
        report['melting_point_depression_K'] = round(liq.get('melting_point_depression', 0), 1)
    T = temperature if temperature > 0 else (liq.get('liquidus_temperature', 1873))
    report['analysis_temperature_K'] = round(T, 1)
    props = call_tool('calculate_all_properties', composition=composition, temperature=T, phase='liquid')
    if props.get('status') == 'success':
        alloy = props.get('alloy', {})
        report['mixing_enthalpy_J'] = alloy.get('molar_enthalpy_J_per_mol')
        report['gibbs_energy_J'] = alloy.get('gibbs_energy_J_per_mol')
        report['entropy_J_K'] = alloy.get('entropy_J_per_mol_K')
    activities = {}
    for elem in composition:
        r = call_tool('calculate_activity', composition=composition, component=elem, temperature=T, phase='liquid')
        if r.get('status') == 'success':
            activities[elem] = {'activity': r.get('activity'), 'gamma': r.get('activity_coefficient')}
    report['activities'] = activities
    report['status'] = 'success'
    return report

def batch_precipitation_scan(composition, phase_types, solution_phase='LIQUID'):
    results = []
    for phase in phase_types:
        r = call_tool('calculate_precipitation_temperature', composition=composition, solute=phase, solution_phase=solution_phase)
        entry = {'phase': phase}
        if r.get('status') == 'success':
            T = r.get('precipitation_temperature')
            entry['precipitation_K'] = round(T, 1) if T else None
            entry['precipitation_C'] = round(T - 273.15, 1) if T else None
        elif r.get('status') == 'no_precipitation':
            entry['precipitation_K'] = None
            entry['message'] = r.get('message', 'no precipitation')
        else:
            entry['error'] = r.get('message', '')
        results.append(entry)
    results.sort(key=lambda x: x.get('precipitation_K') or 0, reverse=True)
    return {'status': 'success', 'composition': composition, 'solution_phase': solution_phase, 'results': results}
